import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const scope={window:{}};vm.runInNewContext(fs.readFileSync('js/nagweb-story-model.js','utf8'),scope);
const model=scope.window.NAGWEB_STREAM_MODEL,plain=x=>JSON.parse(JSON.stringify(x)),defaults=model.config({kind:'cascade-drop'}),center=n=>({x:(n.upper[0].x+n.lower[1].x)/2,y:(n.upper[0].y+n.lower[1].y)/2});
assert.equal(defaults.rotation,100);assert.equal(defaults.cardSize,78);assert.equal(defaults.cardRatio,'1:1');assert.equal(model.config({kind:'cascade-drop',rotation:999,cardSize:999}).rotation,200);assert.equal(model.config({kind:'cascade-drop',rotation:-1,cardSize:-1}).cardSize,50);assert.equal(model.config({kind:'cascade-drop',cardRatio:'frame'}).cardRatio,'frame');
for(const count of [2,4,8])for(const [width,height] of [[1280,720],[390,844]])for(const rotation of [0,100,200])for(const cardRatio of ['auto','frame','1:1','16:9','9:16']){
 const cfg={kind:'cascade-drop',rotation,cardRatio,frameRatio:'auto'},pose=p=>plain(model.layout(width,height,cfg,p,count,1.6)),start=pose(0),hold=pose(.72),seen=new Set();
 assert.equal(start.length,count);assert.deepEqual(start,pose(1),'Loop closes after the pile has left');assert.ok(start.every(n=>n.alpha===0&&!n.visible));assert.ok(hold.every(n=>n.alpha===1&&n.arrival===1));assert.deepEqual(hold,pose(.78),'The completed pile holds before the sweep');assert.ok(pose(.999).every(n=>!n.visible));
 for(let sample=0;sample<96;sample++)for(const n of pose(sample/96)){
  if(n.visible)seen.add(n.slot);assert.equal(n.alpha,n.visible?1:0);assert.equal(n.depth,n.slot);assert.ok(n.width<=width+7&&n.height<=height+7&&n.width>=1&&n.height>=1,'Partial cards allocate bounded canvases');assert.deepEqual([n.textureWidth,n.textureHeight,n.corner],[start[n.slot].textureWidth,start[n.slot].textureHeight,start[n.slot].corner]);
  const [a,b]=n.upper,[d,e]=n.lower,u={x:b.x-a.x,y:b.y-a.y},v={x:d.x-a.x,y:d.y-a.y};assert.ok(Math.abs(u.x*v.x+u.y*v.y)<1e-6,'Rotating cards remain rectangular');assert.ok(Math.abs(Math.hypot(u.x,u.y)/Math.hypot(v.x,v.y)-(cardRatio==='frame'?(width-Math.min(width,height)*.12)/(height-Math.min(width,height)*.12):model.ratios[cardRatio]||1.6))<1e-7);assert.ok(Math.abs(e.x-b.x-d.x+a.x)<1e-7&&Math.abs(e.y-b.y-d.y+a.y)<1e-7);if(rotation===0)assert.equal(n.angle,0);for(const p of n.upper.concat(n.lower))assert.ok(Number.isFinite(p.x)&&Number.isFinite(p.y));
 }
 assert.equal(seen.size,count);assert.ok(center(pose(.9)[0]).y>center(hold[0]).y,'The pile sweeps down');const sweep=pose(.91);for(let i=1;i<count;i++)assert.ok(Math.abs((center(sweep[i]).y-center(hold[i]).y)-(center(sweep[0]).y-center(hold[0]).y))<1e-7,'All settled images leave together');
 const a=pose(.237),b=plain(model.layout(width*2,height*2,cfg,.237,count,1.6));for(let i=0;i<count;i++)for(const side of ['upper','lower'])a[i][side].forEach((p,j)=>{for(const key of ['x','y'])assert.ok(Math.abs(b[i][side][j][key]-p[key]*2)<1e-7);});
}
const pose=(p,extra={})=>plain(model.layout(1280,720,{...defaults,...extra},p,4)),span=1/(4-3*.35);assert.ok(pose(.62*span*.7)[0].arrival>1,'The landing has a small settling overshoot');assert.ok(pose(.05)[0].arrival>0&&pose(.05).slice(1).every(n=>n.arrival===0),'Images start falling one at a time');assert.notEqual(pose(.72)[0].angle,pose(.72)[1].angle);assert.ok(pose(.72,{cardSize:95})[0].textureWidth>pose(.72,{cardSize:50})[0].textureWidth);assert.ok(pose(.72,{padding:20})[0].textureWidth<pose(.72,{padding:0})[0].textureWidth);assert.equal(model.layout(1280,720,defaults,0,1).length,2);assert.equal(model.layout(1280,720,defaults,0,999).length,8);
const scroll={...defaults,turns:3,start:20,end:80};assert.equal(model.phase(.5,scroll,true),1.5);assert.deepEqual(plain(model.layout(1280,720,scroll,.1,4,1,true)),plain(model.layout(1280,720,scroll,.9,4,1,true)));const exported=vm.runInNewContext('('+scope.window.NAGWEB_CREATE_STREAM_MODEL.toString()+')()');assert.deepEqual(plain(exported.layout(390,844,scroll,.317,4,1,true)),plain(model.layout(390,844,scroll,.317,4,1,true)));
console.log('Cascade Drop: 2–8 images, staggered falls/settling/hold/joint sweep, rotation 0–200%, size 50–95%, aspect preservation/frame ratio, bounded canvases/stable textures, responsive geometry, scroll and exported factory OK');
